exec('''
net=[[0,1,0,0],[2,3,4,5],[0,6,0,0]]
cells={(r,c):L for r,row in enumerate(net) for c,L in enumerate(row) if L}
neg=lambda v: tuple(-x for x in v)
start=min(cells)
frames={start:((0,0,-1),(1,0,0),(0,1,0))}
stack=[start]
while stack:
    r,c=stack.pop(); n,e,no=frames[(r,c)]
    for (dr,dc),nf in (((0,1),(e,neg(n),no)),((0,-1),(neg(e),n,no)),((-1,0),(no,e,neg(n))),((1,0),(neg(no),e,n))):
        q=(r+dr,c+dc)
        if q in cells and q not in frames: frames[q]=nf; stack.append(q)
normal={cells[p]:f[0] for p,f in frames.items()}
''')
result=[L for L in normal if normal[L]==neg(normal[3])][0]
